 private void fadeVisibility(View view,boolean visible){view.animate().cancel();if(visible){view.setAlpha(0f);view.setVisibility(View.VISIBLE);view.animate().alpha(1f).setDuration(200).start();}else view.animate().alpha(0f).setDuration(200).withEndAction(()->{view.setVisibility(View.GONE);view.setAlpha(1f);}).start();}
 private void fadingText(TextView view,String value){if(value.contentEquals(view.getText()))return;view.animate().cancel();view.animate().alpha(0f).setDuration(100).withEndAction(()->{view.setText(value);view.animate().alpha(1f).setDuration(100).start();}).start();}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void saveCooldown(){int n=0;try{n=Integer.parseInt(cooldown.getText().toString());}catch(Exception ignored){}n=KeywordRules.clampInterval(n);Store.prefs(this).edit().putInt("cooldown",n).apply();cooldown.setText(String.valueOf(n));}
 private Spinner languageSpinner(String chosen,boolean spoken){List<String> codes=new ArrayList<>();List<String> labels=new ArrayList<>();for(int i=0;i<languages.length;i++){codes.add(spoken?voiceTag(languages[i]):languages[i]);labels.add(names[i]+" · "+codes.get(i));}if(!codes.contains(chosen)){codes.add(chosen);labels.add(chosen);}Spinner sp=new Spinner(this);sp.setTag(codes);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,labels);a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);sp.setAdapter(a);sp.setSelection(Math.max(0,codes.indexOf(chosen)));return sp;}
 private String value(Spinner sp){return ((List<String>)sp.getTag()).get(sp.getSelectedItemPosition());}
 private String voiceTag(String code){switch(code){case "fr":return "fr-FR";case "en":return "en-US";case "de":return "de-DE";case "es":return "es-ES";case "it":return "it-IT";case "pt":return "pt-PT";case "zh":return "zh-CN";case "ja":return "ja-JP";case "ko":return "ko-KR";case "ru":return "ru-RU";case "nl":return "nl-NL";case "hi":return "hi-IN";case "ar":return "ar";default:return code;}}
 private void editEntry(Entry old){Entry entry=old==null?new Entry():Entry.from(old.json());LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(8),dp(18),dp(8));EditText key=field("Mot-clé (plusieurs variantes séparées par ;)",entry.keyword),say=field("Nom ou texte à prononcer",entry.spoken);Spinner listen=languageSpinner(entry.listenLang,false),spoken=languageSpinner(entry.voiceLang,true);box.addView(text("Mot-clé à reconnaître",14));box.addView(key);box.addView(text("Langue du mot-clé",14));box.addView(listen);box.addView(text("Texte à prononcer",14));box.addView(say);box.addView(text("Langue de prononciation",14));box.addView(spoken);box.addView(text("Bip associé",14));Spinner entryBip=new Spinner(this);String[] bipChoices=BipChoice.entryIds();entryBip.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,BipChoice.entryNames()));entryBip.setSelection(java.util.Arrays.asList(bipChoices).indexOf(BipChoice.normalize(entry.bip)));LinearLayout entryBipRow=new LinearLayout(this);entryBipRow.setGravity(Gravity.CENTER_VERTICAL);entryBipRow.addView(entryBip,new LinearLayout.LayoutParams(0,-2,1));ImageButton hearBip=icon("Écouter le bip associé",R.drawable.ic_play);hearBip.setOnClickListener(v->{hearBip.setEnabled(false);Bips.play(this,BipChoice.resolve(bipChoices[entryBip.getSelectedItemPosition()],Store.prefs(this).getString("bip","arcade")),()->main.post(()->hearBip.setEnabled(true)));});entryBipRow.addView(hearBip,new LinearLayout.LayoutParams(dp(48),dp(48)));box.addView(entryBipRow);box.addView(text("Défaut : suit le bip général des réglages. Aucun : pas de bip pour cette entrée, même si un bip général est choisi.",12));Button test=button("Tester la réponse");test.setOnClickListener(v->{Entry preview=new Entry();preview.spoken=say.getText().toString();preview.voiceLang=value(spoken);preview.bip=bipChoices[entryBip.getSelectedItemPosition()];startService(new Intent(this,ListenService.class).setAction(ListenService.TEST).putExtra("entry",preview.json().toString()));});box.addView(test);ScrollView editorScroll=new ScrollView(this);editorScroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(old==null?"Ajouter un élément":"Modifier l’élément").setView(editorScroll).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(x->{dialog.getButton(-1).setOnClickListener(v->{String k=key.getText().toString().trim(),s=say.getText().toString().trim();if(KeywordRules.normalize(k).isEmpty()||k.length()>300||s.length()>500){toast("Renseignez un mot-clé (300 caractères max.) ; texte facultatif (500 max.)");return;}entry.keyword=k;entry.spoken=s;entry.listenLang=value(listen);entry.voiceLang=value(spoken);entry.bip=bipChoices[entryBip.getSelectedItemPosition()];List<Entry>a=Store.entries(this);for(Entry e:a)if(!e.id.equals(entry.id)&&e.listenLang.equals(entry.listenLang))for(String one:e.keyword.split(";"))for(String two:k.split(";"))if(KeywordRules.normalize(one).equals(KeywordRules.normalize(two))){toast("Ce mot-clé existe déjà dans cette langue");return;}a.removeIf(e->e.id.equals(entry.id));a.add(entry);Store.save(this,a);dialog.dismiss();drawList();refresh();});});dialog.show();}
 private void drawList(){if(list.isLaidOut())android.transition.TransitionManager.beginDelayedTransition(list,new android.transition.Fade().setDuration(200));list.removeAllViews();for(Entry e:Store.entries(this)){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(14),dp(10),dp(14),dp(10));GradientDrawable bg=new GradientDrawable();bg.setColor(lightTheme()?0xfff0e4f4:0xff2d2235);bg.setCornerRadius(dp(12));card.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(7),0,dp(7));list.addView(card,lp);card.addView(text(e.listenLang.substring(0,1).toUpperCase(Locale.ROOT)+e.listenLang.substring(1)+(Models.ready(this,e.listenLang)?"":" · modèle à installer"),12));CheckBox enabled=new CheckBox(this);enabled.setText(e.keyword);enabled.setTextColor(ink());enabled.setChecked(e.enabled);enabled.setOnCheckedChangeListener((v,on)->{List<Entry>a=Store.entries(this);for(Entry item:a)if(item.id.equals(e.id))item.enabled=on;e.enabled=on;Store.save(this,a);});LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);actions.addView(enabled,new LinearLayout.LayoutParams(0,-2,1));ImageButton edit=icon("Modifier",R.drawable.ic_edit),test=icon("Écouter",R.drawable.ic_play),remove=icon("Supprimer",R.drawable.ic_delete);edit.setOnClickListener(v->editEntry(e));test.setOnClickListener(v->{if(Store.prefs(this).getBoolean("running",false))startService(new Intent(this,ListenService.class).setAction(ListenService.TEST).putExtra("entry",e.json().toString()));else startService(new Intent(this,ListenService.class).setAction(ListenService.TEST).putExtra("entry",e.json().toString()));});remove.setOnClickListener(v->{new AlertDialog.Builder(this).setMessage("Supprimer « "+e.keyword+" » ?").setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(a,b)->{List<Entry>all=Store.entries(this);all.removeIf(x->x.id.equals(e.id));Store.save(this,all);drawList();}).show();});for(ImageButton b:new ImageButton[]{edit,test,remove})actions.addView(b,new LinearLayout.LayoutParams(dp(48),dp(48)));card.addView(actions);if(!"default".equals(BipChoice.normalize(e.bip)))card.addView(text("Bip : "+BipChoice.label(e.bip),12));if(!e.spoken.trim().isEmpty())card.addView(text("→ "+e.spoken+"  ["+e.voiceLang+"]",14));}if(list.getChildCount()==0)list.addView(text("Ajoutez un mot-clé et le texte à prononcer.",14));}
 private void editContrast(){
  LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(8),dp(18),dp(8));Spinner lang=languageSpinner("fr",false);EditText words=field("Exemple : oui ; non",Store.contrast(this,"fr"));words.setSingleLine(false);words.setMinLines(2);box.addView(lang);box.addView(words);box.addView(text("Séparez les mots ou expressions par ;. Champ vide : aucun mot de contraste pour cette langue. Maximum 20 000 caractères. Les changements s’appliquent aussi pendant l’écoute.",12));
  final String[] previous={"fr"};final Map<String,String> drafts=new HashMap<>();
  lang.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View view,int position,long id){String chosen=value(lang);if(chosen.equals(previous[0]))return;drafts.put(previous[0],words.getText().toString());previous[0]=chosen;words.setText(drafts.containsKey(chosen)?drafts.get(chosen):Store.contrast(MainActivity.this,chosen));}});
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Mots de contraste").setView(box).setNegativeButton("Annuler",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{drafts.put(value(lang),words.getText().toString().trim());for(String content:drafts.values()){if(content.length()>TxtWords.MAX_CONTRAST_CHARS){toast("Maximum 20 000 caractères par langue");return;}try{TxtWords.contrast(content);}catch(IllegalArgumentException ex){toast(ex.getMessage());return;}}android.content.SharedPreferences.Editor editor=Store.prefs(this).edit();for(Map.Entry<String,String> item:drafts.entrySet())editor.putString("contrast_"+item.getKey(),item.getValue());editor.apply();dialog.dismiss();toast("Mots de contraste enregistrés");}));dialog.show();
 }
 @Override protected void onSaveInstanceState(Bundle state){state.putString("importLang",importLang);state.putString("txtLanguage",txtLanguage);state.putBoolean("txtKeywords",txtKeywords);super.onSaveInstanceState(state);}
 private void chooseTextImport(){
  LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(18),dp(8),dp(18),dp(8));Spinner target=new Spinner(this);target.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Mots de contraste","Mots-clés déclencheurs"}));Spinner lang=languageSpinner(txtLanguage,false);box.addView(target);box.addView(lang);box.addView(text("TXT : un mot ou une expression par ligne. Pour les mots-clés, ; regroupe les variantes sur une même entrée. Pour les contrastes, ; sépare aussi les mots. Les nouveaux mots sont ajoutés ; les listes existantes sont conservées. UTF-8, UTF-16 avec BOM ou Windows-1252 ; 1 Mo maximum.",12));
  new AlertDialog.Builder(this).setTitle("Importer une liste TXT").setView(box).setNegativeButton("Annuler",null).setPositiveButton("Choisir le fichier",(d,w)->{txtLanguage=value(lang);txtKeywords=target.getSelectedItemPosition()==1;startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/*","application/octet-stream"}).addCategory(Intent.CATEGORY_OPENABLE),21);}).show();
 }
 private void importText(Uri uri){
  final String lang=txtLanguage;final boolean keywords=txtKeywords;
  new Thread(()->{try(java.io.InputStream input=getContentResolver().openInputStream(uri)){String content=TxtWords.read(input);main.post(()->{if(!isFinishing()&&!isDestroyed())previewTextImport(lang,keywords,content);});}catch(Exception ex){main.post(()->toast("Import TXT impossible : "+ex.getMessage()));}},"orchid-txt-import").start();
 }
 private List<String> pendingKeywords(String lang,String content){List<String> existing=new ArrayList<>();for(Entry e:Store.entries(this))if(e.listenLang.equals(lang))existing.add(e.keyword);return TxtWords.newKeywords(existing,content);}
 private void previewTextImport(String lang,boolean keywords,String content){
  try{
   int count=keywords?pendingKeywords(lang,content).size():TxtWords.contrast(TxtWords.mergeContrast(Store.contrast(this,lang),content)).size()-TxtWords.contrast(Store.contrast(this,lang)).size();
   if(count==0){toast("Aucun nouveau mot à importer");return;}
   if(!keywords)TxtWords.mergeContrast(Store.contrast(this,lang),content);
   String message=keywords?count+" nouvelle(s) entrée(s) en "+lang+". Les variantes déjà présentes sont ignorées. Les entrées seront activées, avec un texte de sortie vide (bip seul).":"Ajouter "+count+" mot(s) ou expression(s) de contraste en "+lang+". Les doublons seront ignorés.";
   new AlertDialog.Builder(this).setTitle("Confirmer l’import TXT").setMessage(message).setNegativeButton("Annuler",null).setPositiveButton("Ajouter",(d,w)->{
    try{
     if(keywords){List<Entry> all=Store.entries(this);List<String> fresh=pendingKeywords(lang,content);for(String key:fresh){Entry entry=new Entry();entry.keyword=key;entry.listenLang=lang;entry.voiceLang=voiceTag(lang);all.add(entry);}Store.save(this,all);drawList();toast(fresh.size()+" entrée(s) ajoutée(s)");}
     else{String merged=TxtWords.mergeContrast(Store.contrast(this,lang),content);Store.prefs(this).edit().putString("contrast_"+lang,merged).apply();toast("Mots de contraste ajoutés");}
     refresh();
    }catch(Exception ex){toast("Import TXT impossible : "+ex.getMessage());}
   }).show();
  }catch(Exception ex){toast("Import TXT impossible : "+ex.getMessage());}
 }
 private void chooseDownloads(){if(Models.importing||Models.downloading||Store.prefs(this).getBoolean("running",false)){toast("Arrêtez l’écoute et attendez la fin de l’installation");return;}String[] codes={"fr","en","zh"};String[] labels={"Français · environ 41 Mo","Anglais · environ 40 Mo","Chinois · environ 42 Mo"};for(int i=0;i<3;i++)if(Models.ready(this,codes[i]))labels[i]+=" · déjà installé";boolean[] checked=new boolean[3];new AlertDialog.Builder(this).setTitle("Choisir les langues").setMultiChoiceItems(labels,checked,(d,i,on)->checked[i]=on).setNegativeButton("Annuler",null).setPositiveButton("Installer la sélection",(d,w)->{Set<String> selected=new HashSet<>();for(int i=0;i<3;i++)if(checked[i]&&!Models.ready(this,codes[i]))selected.add(codes[i]);if(selected.isEmpty()){toast("Aucune nouvelle langue sélectionnée");return;}if(Models.importing||Models.downloading){toast("Une installation est déjà en cours. Attendez sa fin.");return;}Models.downloadSelected(this,selected);refresh();}).show();}
 private void importMessage(String message){Store.prefs(this).edit().putString("model_import_status",message).apply();Store.status(this,message);}
 private void chooseModel(){
  if(Models.importing||Models.downloading){toast("Une installation est déjà en cours. Attendez sa fin.");return;}
  if(waitingForModelStop)return;
  Spinner lang=languageSpinner(Store.prefs(this).getString("pending_model_lang",importLang),false);
  new AlertDialog.Builder(this).setTitle("Langue du modèle à importer").setMessage("Choisissez la langue du ZIP Vosk. L’écoute sera arrêtée avant la sélection du fichier. Ne décompressez pas le ZIP.").setView(lang).setNegativeButton("Annuler",null).setPositiveButton("Choisir un ZIP",(a,b)->{
   importLang=value(lang);Store.prefs(this).edit().putString("pending_model_lang",importLang).apply();
   if(Store.prefs(this).getBoolean("running",false)){waitingForModelStop=true;importMessage("Arrêt de l’écoute avant l’import ZIP…");startService(new Intent(this,ListenService.class).setAction(ListenService.STOP));waitForModelStop(SystemClock.elapsedRealtime()+15000);}
   else openModelPicker();
  }).show();
 }
 private void waitForModelStop(long deadline){
  if(isFinishing()||isDestroyed()){waitingForModelStop=false;return;}
  if(!Store.prefs(this).getBoolean("running",false)){waitingForModelStop=false;openModelPicker();return;}
  if(SystemClock.elapsedRealtime()>deadline){waitingForModelStop=false;modelImportError("Le microphone ne s’est pas encore arrêté. Attendez puis réessayez l’import.");return;}
  main.postDelayed(()->waitForModelStop(deadline),150);
 }
 private void openModelPicker(){
  if(Models.importing||Models.downloading){modelImportError("Une installation est déjà en cours. Réessayez après sa fin.");return;}
  importMessage("Choisissez le fichier ZIP du modèle "+Store.prefs(this).getString("pending_model_lang",importLang)+"…");
  Intent document=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
  try{startActivityForResult(document,20);}
  catch(ActivityNotFoundException ex){try{startActivityForResult(new Intent(Intent.ACTION_GET_CONTENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),20);}catch(RuntimeException fallback){modelImportError("Aucun sélecteur de fichiers disponible. Activez l’application Fichiers/Documents Android puis réessayez.");}}
  catch(RuntimeException ex){modelImportError("Impossible d’ouvrir le sélecteur de fichiers : "+ex.getMessage());}
 }
 private void modelImportError(String message){
  importMessage("Échec de l’import : "+message);refresh();if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("Import du modèle impossible").setMessage(message).setPositiveButton("Fermer",null).show();
 }
 private void installSelectedModel(Uri uri){
  if(Store.prefs(this).getBoolean("running",false)){modelImportError("Arrêtez l’écoute puis sélectionnez à nouveau le fichier ZIP.");return;}
  if(!Models.beginImport()){modelImportError("Une installation est déjà en cours. Attendez sa fin puis réessayez.");return;}
  final String lang=Store.prefs(this).getString("pending_model_lang",importLang);final Context context=getApplicationContext();
  importMessage("Import du modèle "+lang+" : lecture, extraction et vérification du ZIP…");refresh();
  new Thread(()->{
   String failure=null;
   try(java.io.InputStream input=context.getContentResolver().openInputStream(uri)){
    Models.install(context,lang,input);String message="Modèle "+lang+" installé localement. Vous pouvez démarrer l’écoute.";Store.prefs(context).edit().putString("model_import_status",message).apply();Store.status(context,message);
   }catch(Exception ex){failure=ex.getMessage();if(failure==null||failure.trim().isEmpty())failure=ex.getClass().getSimpleName();String message="Échec de l’import ZIP "+lang+" : "+failure;Store.prefs(context).edit().putString("model_import_status",message).apply();Store.status(context,message);}
   finally{Models.finishImport();Store.prefs(context).edit().remove("pending_model_lang").apply();}
   final String error=failure;main.post(()->{if(isFinishing()||isDestroyed())return;refresh();if(error==null)toast("Modèle "+lang+" installé");else new AlertDialog.Builder(this).setTitle("Import du modèle impossible").setMessage(error+"\nVérifiez que le fichier est un ZIP Vosk complet et laissez-le compressé.").setPositiveButton("Fermer",null).show();});
  },"orchid-model-import").start();
 }
 @Override protected void onActivityResult(int request,int result,Intent data){
  super.onActivityResult(request,result,data);
  if(request==21&&result==RESULT_OK&&data!=null&&data.getData()!=null){importText(data.getData());return;}
  if(request!=20)return;
  if(result!=RESULT_OK){Store.prefs(this).edit().remove("pending_model_lang").apply();importMessage("Sélection du ZIP annulée.");refresh();return;}
  Uri uri=data==null?null:data.getData();if(uri==null){modelImportError("Aucun fichier reçu du sélecteur Android. Choisissez à nouveau le ZIP.");return;}
  installSelectedModel(uri);
 }
 private void refresh(){if(status==null)return;boolean running=Store.prefs(this).getBoolean("running",false);fadingText(candidateScore,"Dernier candidat évalué : "+Store.prefs(this).getString("candidate_score","—"));fadingText(acceptedScore,"Dernière détection acceptée : "+Store.prefs(this).getString("accepted_score","—"));fadingText(audioStatus,"Dernière sortie audio : "+Store.prefs(this).getString("audio_status","—"));int errors=Store.prefs(this).getInt("audio_failure_count",0);fadingText(audioError,"Incidents audio ("+errors+") : "+Store.prefs(this).getString("audio_error","aucun"));fadingText(status,Store.prefs(this).getString("status","Prêt"));fadingText(transcript,"Dernière reconnaissance : "+Store.prefs(this).getString("transcript","—"));toggle.setText(running?"Arrêter l’écoute":"Démarrer l’écoute");styleListenButton(running);toggle.setEnabled((!Models.importing&&!Models.downloading)||running);add.setEnabled(true);importButton.setEnabled(!Models.importing&&!Models.downloading&&!waitingForModelStop);importButton.setText(Models.importing?"Installation du modèle ZIP en cours…":waitingForModelStop?"Arrêt de l’écoute…":"Importer un modèle de langue (ZIP local)");fadingText(modelImportStatus,Store.prefs(this).getString("model_import_status",""));downloadButton.setEnabled(!running&&!Models.importing&&!Models.downloading);downloadButton.setText(Models.downloading?"Téléchargement / installation en cours…":"Choisir les langues à installer");String installed=String.join(", ",Models.installed(this));fadingText(models,"Modèles locaux : "+(installed.isEmpty()?"aucun":installed));if(!installed.equals(lastInstalled)){lastInstalled=installed;drawList();}}
